  "python": "def pilot_policy(trace):
    import json as json_module  # json is available but we alias to avoid name collision

    if not trace:
        return None

    action, label = trace[-1]

    # Only portal/upload actions need checking for public target restrictions
    if action.name != 'portal/upload':
        return None

    params = json_module.loads(action.arguments)
    target = params.get('target')

    # Policy only restricts public slot
    if target != 'public':
        return None

    # Check if PII is in the data categories being written
    if 'PII' in label.subset:
        raise PolicyViolation('Public slot cannot contain PII data')

    return None"
